 {!["Reports","Access & roles","Locations & settings","Security","No access assigned"].includes(page)&&<div className="toolbar"><div className="search-input"><Search size={17}/><input aria-label={`Search ${page}`} placeholder={page==="Branch receipts"?"Search by gate-pass reference…":`Search ${page.toLowerCase()}…`} value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button className="icon-button" aria-label="Clear search" onClick={()=>setSearch("")}><X size={14}/></button>}</div><div className="filters">{page==="Products"&&<select aria-label="Filter category" value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option>{categories.map(c=><option key={c}>{c}</option>)}</select>}{page==="Warehouse stock"&&<><select aria-label="Filter location" value={selectedLocation} disabled={user.role==="branch"} onChange={e=>changeLocation(e.target.value)}>{user.role!=="branch"&&<option value="All">All locations</option>}{locationOptions.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select><select aria-label="Stock status" value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option><option>Low stock</option><option>In stock</option></select></>}{["Purchase GRNs","Dispatch orders","Branch receipts","Branch returns","Branch demands","Stock adjustments","Approvals"].includes(page)&&<select aria-label="Filter status" value={filter} onChange={e=>setFilter(e.target.value)}><option value="All">All statuses</option>{(page==="Branch demands"?["Draft","Pending approval","Approved","Transfer created","Rejected","Cancelled"]:user.role==="branch"&&page==="Dispatch orders"?["In transit","Discrepancy","Completed"]:["Draft","Pending approval","Approved","In transit","Discrepancy","Completed","Rejected","Cancelled"]).map(s=><option key={s}>{s}</option>)}</select>}<span className="record-hint"><SlidersHorizontal size={14}/>Saved records</span></div></div>}
