 {page==="Warehouse stock"&&<><div className="stock-summary"><span><Warehouse size={19}/><b>{selectedLocationName}</b></span><p>Active, configured products appear here automatically at 0 until stock is received or added. Each item keeps its own stock unit.</p><button className="button secondary" onClick={()=>{const d=stockExport(stockRows);csv("stock",d.headers,d.rows);}}><Download size={15}/>Export stock</button></div><section className="card">{stockRows.length?<div className="table-scroll"><table><thead><tr><th>Product</th><th>Location</th><th className="numeric">On hand</th><th>Stock unit</th>{canCost&&<><th className="numeric">Average cost</th><th className="numeric">Stock value</th></>}<th>Stock status</th></tr></thead><tbody>{stockRows.map(s=><tr key={s.locationId+s.productId}><td><strong>{product(s.productId).name}</strong><small className="block muted">{product(s.productId).sku}</small></td><td>{location(s.locationId)}</td><td className="numeric stock-qty">{num(s.qty)}{s.countReviewRequired&&<small className="block count-review">Verify physical count</small>}</td><td>{unitSymbol(product(s.productId).baseUnit)}</td>{canCost&&<><td className="numeric">{s.unstocked?"—":money(s.avgCost)}</td><td className="numeric">{money(s.qty*s.avgCost)}</td></>}<td><Badge status={low(s)?"Low stock":"In stock"}/></td></tr>)}</tbody></table></div>:<Empty/>}</section></>}
 {["Purchase GRNs","Dispatch orders","Branch receipts","Branch returns","Stock adjustments","Approvals"].includes(page)&&<>{page==="Purchase GRNs"&&selectedLocation!=="All"&&selectedLocation!=="WH"&&<div className="info-banner"><Warehouse size={20}/><p>Purchase GRNs are received at Central Warehouse. Switch to Central Warehouse to view its purchase register. New GRNs always add stock there.</p></div>}{(page==="Branch receipts"||user.role==="branch"&&page==="Dispatch orders")&&<div className="info-banner"><ClipboardCheck size={20}/><div><strong>Receive against an existing gate pass</strong><p>Search its reference above, open the document and enter good and damaged quantities in each product stock unit. Shortages are calculated automatically.</p></div></div>}{page==="Approvals"&&<div className="info-banner"><ShieldCheck size={20}/><div><strong>Independent review protects every stock movement</strong><p>Requests need independent review. Super Admin overrides require a recorded reason. Discrepancies can be received, returned or recognized as a loss.</p></div></div>}<section className="card"><div className="card-heading compact"><h2>{page==="Approvals"?"Review queue":"Document register"} <span className="inline-count">{visibleDocs.length}</span></h2><span className="small muted">Open a reference to view its workflow</span></div><DocTable/></section></>}
